// Separa o código Pix (BR Code) numa mensagem própria, para o cliente copiar com um toque (IA-RF-06).
const LIMITE = 4096; // limite de caracteres de uma mensagem de texto no WhatsApp
const PIX = /000201[^\n]*6304[0-9A-Fa-f]{4}/;
const resposta = String($input.first().json.output ?? '').trim();
const codigo = resposta.match(PIX)?.[0];
const texto = codigo ? resposta.replace(codigo, '').trim() : resposta;
const mensagens = [texto, codigo].filter(Boolean).map((m) => m.slice(0, LIMITE));
return [{ json: { mensagens: mensagens.length ? mensagens : ['Desculpe, não consegui responder agora. Pode repetir, por favor?'] } }];
